#ifndef MODEL_H
#define MODEL_H

#include <stdint.h>

// Weights

typedef struct {
  uint32_t vocab_size;
  uint32_t embed_dim;
  uint32_t hidden_dim;
  uint32_t output_dim;
  float *embedding;
  float *fc1_weight;
  float *fc1_bias;
  float *fc2_weight;
  float *fc2_bias;
} Weights;

// Load model weights from weights.bin
int load_weights(const char *path, Weights *w);
void free_weights(Weights *w);

// Vocab

#define MAX_WORD_LEN 64

// Hash map, this part of the code is generated by Claude
typedef struct {
  char word[MAX_WORD_LEN];
  int index;
} VocabBucket;

typedef struct {
  uint32_t size;
  uint32_t cap;
  VocabBucket *buckets;
} Vocab;

// End Claude generated code

// Load vocab from vocab.bin
int load_vocab(const char *path, Vocab *v);
void free_vocab(Vocab *v);

// Model

float predict(const int *token_indices, int count, const Weights *w);

// Tokenizer

int tokenize(const char *text, const Vocab *vocab, int *out_indices, int max_tokens);

#endif // !MODEL_H
